import{_ as s,a0 as o,w as i,s as r,ao as d,I as a,x as n,a1 as u,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Ubuntu每日小技巧 – 深入理解应用菜单和按钮 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧 – 深入理解应用菜单和按钮 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧 – 深入理解应用菜单和按钮 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧 – 深入理解应用菜单和按钮 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons","title":"Ubuntu每日小技巧 – 深入理解应用菜单和按钮","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons.md"};function b(T,t,m,g,f,U){const e=o("Link");return i(),r("div",null,[t[11]||(t[11]=d(`<h1 id="ubuntu每日小技巧-–-深入理解应用菜单和按钮" tabindex="-1">Ubuntu每日小技巧 – 深入理解应用菜单和按钮 <a class="header-anchor" href="#ubuntu每日小技巧-–-深入理解应用菜单和按钮" aria-label="Permalink to “Ubuntu每日小技巧 – 深入理解应用菜单和按钮”">​</a></h1><p>Ubuntu是一款很不错的操作系统。它基本上可以做到任何现代操作系统能做的事情，甚至有时候能做的更好。如果你是一个ubuntu新手，那么你现在还有很多不知道的事情。对于那些专家级用户来说十分普通的事情可能对你来说可能就不太普通了，因此这个“ubuntu每日小技巧”系列旨在帮助你和新用户轻松设置管理ubuntu。</p><p>Ubuntu有一个菜单栏。这个主菜单栏是在屏幕的顶端黑色条状栏，其包含了状态菜单或指示器和时间日期，音量键，应用的菜单和窗口管理按钮。</p><p>窗口管理按钮在主菜单（黑色条状栏）的左上角。当年你打开一个程序的时候，主菜单左上角的按钮包括关闭、最小化、最大化、和恢复大小按钮，这些按钮叫做窗口管理按钮。</p><p>应用的菜单位于窗口管理按钮的右侧。当应用打开时才显示应用菜单。</p><p>默认情况下，ubuntu隐藏了窗口应用菜单和管理按钮，只有当你把鼠标放在左侧角里的时候才能看到。如果你打开一个程序但是找不到菜单，只需要把你的鼠标移动到屏幕左上角就可以使它显示出来。</p><p>如果这让你很困惑，而且你想关闭（全局的）应用菜单而使每个程序都有自己的菜单的话，继续向下看。</p><p>运行以下命令以安装或删除应用菜单：</p><pre><code>sudo apt-get autoremove indicator-appmenu
</code></pre><p>运行上面的命令将会删除应用菜单即全局菜单。现在，为了使改变生效，先退出然后再登录回来。</p><p>现在，当你打开一个ubuntu里面的程序的时候，每个程序就会用显示自己的菜单代替把它隐藏在全局菜单或主菜单里。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntuappmenuglobalmenu.png" alt=""></p><p>就是这样! 想返回原来的状态的话,运行下面的命令：</p><pre><code>sudo apt-get install indicator-appmenu
</code></pre><p>使用愉快!</p><hr>`,16)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),u(e,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-understanding-app-menus-buttons/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-understanding-app-menus-buttons/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原创翻译，",-1)),u(e,{href:"http://linux.cn/"},{default:p(()=>[...t[3]||(t[3]=[n("Linux中国",-1)])]),_:1}),t[6]||(t[6]=n(" 荣誉推出",-1))]),a("p",null,[t[9]||(t[9]=n("译者：",-1)),u(e,{href:"https://github.com/crowner"},{default:p(()=>[...t[7]||(t[7]=[n("crowner",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),u(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})])])}const x=s(l,[["render",b]]);export{_ as __pageData,x as default};
